    # Parse lines
    entries = []
    node_pattern = re.compile(r'^n[0-9][0-9]*$')

    for line in lines:
        stripped = line.strip()

        # Skip empty lines and comments
        if not stripped or stripped.startswith('#'):
            continue

        fields = stripped.split()

        # Validate field count
        if len(fields) < 4 or len(fields) > 5:
            break

        try:
            term = int(fields[0])
            if term < 0:
                break
        except ValueError:
            break

        try:
            index = int(fields[1])
            if index < 1:
                break
        except ValueError:
            break

        node = fields[2]
        if not node_pattern.match(node):
            break

        op = fields[3]
        if op not in ('VOTE', 'APPEND', 'COMMIT', 'LEADER'):
            break

        data = None
        if op == 'APPEND':
            if len(fields) != 5:
                break
            data = fields[4]
        else:
            if len(fields) != 4:
                break

        entry = (term, index, node, op, data)

        # Skip exact duplicates
        if entry in entries:
            continue

        entries.append(entry)

    # Group by index, maintaining file order
    by_index = {}
    for entry in entries:
        idx = entry[1]
        if idx not in by_index:
            by_index[idx] = []
        by_index[idx].append(entry)

    if not by_index:
        return "OK"

    indices = sorted(by_index.keys())

    bad_entries = []

    # Global tracking for protocol rules
    votes = {}  # (node, term) -> first index where vote occurred
    leaders = {}  # term -> first index where leader was established

    # First pass: collect violations
    for idx in indices:
        index_entries = by_index[idx]

        # Collect terms at this index in file order
        terms_in_order = [e[0] for e in index_entries]

        # Rule 1: Term monotonicity
        for i in range(1, len(terms_in_order)):
            if terms_in_order[i] < terms_in_order[i-1]:
                if idx not in [b[0] for b in bad_entries]:
                    bad_entries.append((idx, "BAD_TERM_REGRESSION"))
                break

        # Extract operations
        appends = [(e[0], e[4]) for e in index_entries if e[3] == 'APPEND']
        votes_here = [(e[0], e[2]) for e in index_entries if e[3] == 'VOTE']
        commits = [(e[0], e[2]) for e in index_entries if e[3] == 'COMMIT']
        leaders_here = [(e[0], e[2]) for e in index_entries if e[3] == 'LEADER']

        # Rule 5: Conflict detection (same term, different data)
        term_data = {}
        for term, data in appends:
            if term in term_data:
                if term_data[term] != data:
                    if idx not in [b[0] for b in bad_entries]:
                        bad_entries.append((idx, "BAD_CONFLICT"))
                    break
            else:
                term_data[term] = data

        # Rule 4: COMMIT order
        has_append = len(appends) > 0
        if not has_append:
            for commit_term, _ in commits:
                if idx not in [b[0] for b in bad_entries]:
                    bad_entries.append((idx, "BAD_COMMIT_ORDER"))
                break
        else:
            # Winning term = highest term
            winning_term = max(appends, key=lambda x: x[0])[0] if appends else None
            if winning_term is not None:
                for commit_term, _ in commits:
                    if commit_term != winning_term:
                        if idx not in [b[0] for b in bad_entries]:
                            bad_entries.append((idx, "BAD_COMMIT_ORDER"))
                        break

        # Rule 3: Duplicate vote detection
        for commit_term, node in votes_here:
            key = (node, commit_term)
            if key in votes:
                if idx not in [b[0] for b in bad_entries]:
                    bad_entries.append((idx, "BAD_DUPLICATE_VOTE"))
                break
            else:
                votes[key] = idx

        # Rule 3: Leader order
        for leader_term, node in leaders_here:
            if leader_term in leaders:
                if idx not in [b[0] for b in bad_entries]:
                    bad_entries.append((idx, "BAD_LEADER_ORDER"))
                break
            else:
                leaders[leader_term] = idx

    # Rule 2: Log matching (need committed terms from previous indices)
    committed_term = 0
    for idx in indices:
        index_entries = by_index[idx]
        appends = [e for e in index_entries if e[3] == 'APPEND']
        commits = [e for e in index_entries if e[3] == 'COMMIT']

        if appends and commits:
            winning_term = max(appends, key=lambda x: x[0])[0]
            if committed_term > winning_term:
                if idx not in [b[0] for b in bad_entries]:
                    bad_entries.append((idx, "BAD_LOG_MATCH"))
            committed_term = winning_term

    # Collect repair entries (missing COMMITs)
    ins_entries = []
    bad_indices = set(b[0] for b in bad_entries)

    for idx in indices:
        if idx in bad_indices:
            continue
        index_entries = by_index[idx]
        appends = [e for e in index_entries if e[3] == 'APPEND']
        commits = [e for e in index_entries if e[3] == 'COMMIT']

        if appends and not commits:
            winning_term = max(appends, key=lambda x: x[0])[0]
            ins_entries.append((idx, winning_term))

    # Build output
    output = []
    for idx, reason in sorted(bad_entries, key=lambda x: x[0]):
        output.append(f"BAD {idx} {reason}")
    for idx, term in sorted(ins_entries, key=lambda x: (x[0], x[1])):
        output.append(f"INS {term} {idx} COMMIT")

    if not output:
        return "OK"
    return "\n".join(output)


if __name__ == "__main__":
    import sys
