        has_conflict = False
        term_data = {}
        for term, data in appends:
            if term in term_data:
                if term_data[term] != data:
                    has_conflict = True
                    break
            else:
                term_data[term] = data

        if has_conflict:
            if idx not in [b[0] for b in bad_entries]:
                bad_entries.append((idx, "BAD_CONFLICT"))

        # Rule 4: COMMIT order
        has_append = len(appends) > 0
        commit_violation = False

        if not has_append:
            if commits:
                commit_violation = True
        else:
            # Winning term = highest term
            winning_term = max(appends, key=lambda x: x[0])[0] if appends else None
            if winning_term is not None:
                for commit_term, _ in commits:
                    if commit_term != winning_term:
                        commit_violation = True
                        break

        if commit_violation:
            if idx not in [b[0] for b in bad_entries]:
                bad_entries.append((idx, "BAD_COMMIT_ORDER"))

        # Rule 3: Duplicate vote detection
        for commit_term, node in votes_here:
            key = (node, commit_term)
            if key in votes:
                if idx not in [b[0] for b in bad_entries]:
                    bad_entries.append((idx, "BAD_DUPLICATE_VOTE"))
                break
            else:
                votes[key] = idx

        # Rule 3: Leader order
        for leader_term, node in leaders_here:
            if leader_term in leaders:
                if idx not in [b[0] for b in bad_entries]:
                    bad_entries.append((idx, "BAD_LEADER_ORDER"))
                break
            else:
                leaders[leader_term] = idx

        # Record winning APPEND term for log matching
        if appends:
            winning_terms[idx] = max(appends, key=lambda x: x[0])[0]

    # Rule 2: Log matching (need winning APPEND terms from previous indices)
    prev_committed = 0
    for idx in indices:
        if idx in winning_terms:
            if prev_committed > winning_terms[idx]:
                if idx not in [b[0] for b in bad_entries]:
                    bad_entries.append((idx, "BAD_LOG_MATCH"))
            prev_committed = winning_terms[idx]

    # Collect repair entries (missing COMMITs)
    ins_entries = []
    bad_indices = set(b[0] for b in bad_entries)

    for idx in indices:
        if idx in bad_indices:
            continue
        index_entries = by_index[idx]
        appends = [e for e in index_entries if e[3] == 'APPEND']
        commits = [e for e in index_entries if e[3] == 'COMMIT']

        if appends and not commits:
            winning_term = max(appends, key=lambda x: x[0])[0]
            ins_entries.append((idx, winning_term))

    # Build output
    output = []
    for idx, reason in sorted(bad_entries, key=lambda x: x[0]):
        output.append(f"BAD {idx} {reason}")
    for idx, term in sorted(ins_entries, key=lambda x: (x[0], x[1])):
        output.append(f"INS {term} {idx} COMMIT")

    if not output:
        return "OK"
    return "\n".join(output)


